package com.medipanda.controller;
import com.medipanda.model.*; import com.medipanda.repository.*; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.util.*;
@RestController @RequestMapping("/api/admin")
public class AdminController {
 private final UserRepository users; private final PharmacyRepository pharmacies; private final MedicineRepository medicines; private final OrderRepository orders; private final RiderRepository riders; private final ReportRepository reports; private final SiteSettingsRepository site;
 public AdminController(UserRepository u,PharmacyRepository p,MedicineRepository m,OrderRepository o,RiderRepository r,ReportRepository rep,SiteSettingsRepository s){users=u;pharmacies=p;medicines=m;orders=o;riders=r;reports=rep;site=s;}
 @GetMapping("/dashboard") public Map<String,Object> dashboard(){long pending=users.findAll().stream().filter(u->"PENDING".equals(u.getVerificationStatus())).count();return Map.of("users",users.count(),"pharmacies",pharmacies.count(),"medicines",medicines.count(),"orders",orders.count(),"riders",riders.count(),"pendingVerifications",pending,"openReports",reports.findAll().stream().filter(x->!"CLOSED".equals(x.getStatus())).count());}
 @GetMapping("/users") public List<User> users(){return users.findAll();} @GetMapping("/pharmacies") public List<Pharmacy> pharmacies(){return pharmacies.findAll();} @GetMapping("/medicines") public List<Medicine> medicines(){return medicines.findAll();} @GetMapping("/orders") public List<Order> orders(){return orders.findAll();} @GetMapping("/riders") public List<Rider> riders(){return riders.findAll();}
 @GetMapping("/verification-requests") public List<User> verificationRequests(){return users.findAll().stream().filter(u->"PENDING".equals(u.getVerificationStatus())&&Set.of("PHARMACY","RIDER").contains(u.getRole())).toList();}
 @PatchMapping("/verification/{id}/approve") public User approve(@PathVariable String id){User u=users.findById(id).orElseThrow();if(!Set.of("PHARMACY","RIDER").contains(u.getRole()))bad("Only pharmacy/rider applications need approval");u.setEnabled(true);u.setVerificationStatus("APPROVED");u.setRejectionReason(null);User saved=users.save(u);if("PHARMACY".equals(u.getRole())) pharmacies.findByOwnerUserId(u.getId()).ifPresentOrElse(ph->{ph.setOpen(true);if(ph.getDescription()==null||ph.getDescription().equals("Pending verification"))ph.setDescription("Verified MediPanda pharmacy");pharmacies.save(ph);},()->pharmacies.save(Pharmacy.builder().name(u.getName()).area("Dhaka").street("").image("https://images.unsplash.com/photo-1585435557343-3b092031a831?w=1000").rating("New").deliveryTime("25-40 min").description("Verified MediPanda pharmacy").open(true).latitude(23.7806).longitude(90.4070).locationAddress("Dhaka, Bangladesh").ownerUserId(u.getId()).build()));if("RIDER".equals(u.getRole())&&riders.findAll().stream().noneMatch(r->u.getId().equals(r.getUserId())))riders.save(Rider.builder().userId(u.getId()).name(u.getName()).phone(u.getPhone()).vehicle("Bike").status("OFFLINE").latitude(23.7806).longitude(90.4070).earnings(0).build());return saved;}
 @PatchMapping("/verification/{id}/reject") public User reject(@PathVariable String id,@RequestBody(required=false) Map<String,String> body){User u=users.findById(id).orElseThrow();u.setEnabled(false);u.setVerificationStatus("REJECTED");u.setRejectionReason(body==null?"Application needs correction":body.getOrDefault("reason","Application needs correction"));return users.save(u);}
 @PatchMapping("/orders/{orderId}/assign/{riderId}") public Order assign(@PathVariable String orderId,@PathVariable String riderId){Order o=orders.findById(orderId).orElseThrow();Rider r=riders.findById(riderId).orElseThrow();if(Set.of("DELIVERED","CANCELLED").contains(o.getStatus()))bad("Completed or cancelled orders cannot be assigned");if(!"AVAILABLE".equals(r.getStatus())&&!r.getId().equals(o.getRiderId()))bad("Rider is not available");if(o.getRiderId()!=null&&!o.getRiderId().equals(r.getId()))riders.findById(o.getRiderId()).ifPresent(old->{old.setStatus("AVAILABLE");riders.save(old);});r.setStatus("BUSY");riders.save(r);o.setRiderId(r.getId());o.setRiderRequestAt(new Date());if(o.getRejectedRiderIds()==null)o.setRejectedRiderIds(new ArrayList<>());o.getRejectedRiderIds().remove(r.getId());o.setStatus("RIDER_REQUESTED");return orders.save(o);}
 @PatchMapping("/orders/{id}/status") public Order orderStatus(@PathVariable String id,@RequestBody Map<String,String> body){Order o=orders.findById(id).orElseThrow();String st=body.get("status");if(st==null||!Set.of("PENDING","CONFIRMED","PREPARING","READY_FOR_PICKUP","WAITING_FOR_RIDER","RIDER_REQUESTED","RIDER_ACCEPTED","PICKED_UP","ON_THE_WAY","DELIVERED","CANCELLED").contains(st))bad("Invalid order status");o.setStatus(st);return orders.save(o);}
 @PatchMapping("/users/{id}/toggle") public User toggle(@PathVariable String id){User u=users.findById(id).orElseThrow();u.setEnabled(!u.isEnabled());return users.save(u);}
 @PostMapping("/pharmacies") public Pharmacy addPharmacy(@RequestBody Pharmacy p){return pharmacies.save(p);}
 @PutMapping("/pharmacies/{id}") public Pharmacy editPharmacy(@PathVariable String id,@RequestBody Pharmacy p){Pharmacy x=pharmacies.findById(id).orElseThrow();x.setName(p.getName());x.setArea(p.getArea());x.setStreet(p.getStreet());x.setImage(p.getImage());x.setRating(p.getRating());x.setDeliveryTime(p.getDeliveryTime());x.setDescription(p.getDescription());x.setOpen(p.isOpen());x.setLatitude(p.getLatitude());x.setLongitude(p.getLongitude());x.setLocationAddress(p.getLocationAddress());return pharmacies.save(x);}
 @DeleteMapping("/pharmacies/{id}") public void delPharmacy(@PathVariable String id){pharmacies.deleteById(id);}
 @PostMapping("/medicines") public Medicine addMedicine(@RequestBody Medicine m){return medicines.save(m);}
 @PutMapping("/medicines/{id}") public Medicine editMedicine(@PathVariable String id,@RequestBody Medicine m){Medicine x=medicines.findById(id).orElseThrow();x.setName(m.getName());x.setGenericName(m.getGenericName());x.setCategory(m.getCategory());x.setManufacturer(m.getManufacturer());x.setPrice(m.getPrice());x.setOldPrice(m.getOldPrice());x.setStock(Math.max(0,m.getStock()));x.setImage(m.getImage());x.setPrescriptionRequired(m.isPrescriptionRequired());x.setPharmacyId(m.getPharmacyId());return medicines.save(x);}
 @DeleteMapping("/medicines/{id}") public void delMedicine(@PathVariable String id){medicines.deleteById(id);}
 @PutMapping("/site") public SiteSettings updateSite(@RequestBody SiteSettings p){SiteSettings x=site.findAll().stream().findFirst().orElse(SiteSettings.builder().id("main").build());x.setSiteName(p.getSiteName());x.setTagline(p.getTagline());x.setHeroTitle(p.getHeroTitle());x.setHeroText(p.getHeroText());x.setHeroVideoUrl(p.getHeroVideoUrl());x.setLogoUrl(p.getLogoUrl());x.setContactEmail(p.getContactEmail());x.setContactPhone(p.getContactPhone());x.setFooterText(p.getFooterText());x.setMaintenanceMode(p.isMaintenanceMode());return site.save(x);}
 @GetMapping("/reports") public List<Report> allReports(){return reports.findAllByOrderByCreatedAtDesc();}
 @PatchMapping("/reports/{id}") public Report updateReport(@PathVariable String id,@RequestBody Map<String,String> body){Report r=reports.findById(id).orElseThrow();r.setStatus(body.getOrDefault("status",r.getStatus()));r.setAdminReply(body.getOrDefault("adminReply",r.getAdminReply()));r.setUpdatedAt(new Date());return reports.save(r);}
 private void bad(String m){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,m);}
}
